/// The active clauses governing an intended or changed scope, bucketed by how
/// each relates to a covering task's own goal. Produced by
/// [`Lodestar::resolve_governing_clauses`] and consumed by both conformance and
/// `advise`; `(node_id, goal)` pairs preserve which node each clause governs.
#[derive(Debug, Default)]
pub(crate) struct GoverningClauses {
    /// Clauses that hard-lock a node against any change (`forbid_change`).
    pub forbid: Vec<(String, Goal)>,
    /// `governed` bindings to the covering task's own goal — the change is in scope.
    pub in_scope: Vec<(String, Goal)>,
    /// `governed` bindings to a different goal — a change here would drift.
    pub other: Vec<(String, Goal)>,
    /// Clauses governing an intended *procedural* action rather than a changed
    /// file (ADR-0034). Paired with the `workflow:` token they matched, which
    /// occupies the `node_id` slot when flattened — a workflow clause governs an
    /// action, and there is no code node to name.
    pub workflow: Vec<(String, Goal)>,
    /// Goals that were in scope only because the task declared coverage for them
    /// (ADR-0041). Non-empty means the verdict leaned on a declaration, which
    /// caps it at `needs_human`: an agent's own claim about its own breadth is
    /// reviewed, never self-certified.
    pub relied_on_coverage: Vec<String>,
}

impl GoverningClauses {
    /// Flatten the buckets into governing-clause rows (forbids first) — the shape
    /// surfaced by `advise` and by task pickup. Preserves which node each clause
    /// governs and its binding mode, so both callers read one representation.
    pub(crate) fn clauses(&self) -> Vec<GoverningClause> {
        let mut out = Vec::new();
        for (node, goal) in &self.forbid {
            out.push(GoverningClause {
                node_id: node.clone(),
                goal: goal.clone(),
                mode: CodeBindingMode::ForbidChange,
            });
        }
        for (node, goal) in self.in_scope.iter().chain(self.other.iter()) {
            out.push(GoverningClause {
                node_id: node.clone(),
                goal: goal.clone(),
                mode: CodeBindingMode::Governed,
            });
        }
        for (scope, goal) in &self.workflow {
            out.push(GoverningClause {
                node_id: scope.clone(),
                goal: goal.clone(),
                mode: CodeBindingMode::Governed,
            });
        }
        out
    }
}

impl Lodestar {
    /// Complete a task using one authoritative, claim-bounded conformance check
    /// (ADR-0009). The optional semantic judge is not invoked again here.
    ///
    /// `learned` is what the agent concluded, recorded as durable knowledge at
    /// the moment it holds it (ADR-0053). It is deliberately not inferred: the
    /// zero-token write path stands, and an execution log is not a lesson.
    /// Completion is never blocked by omitting it — most tasks teach nothing,
    /// and a gate would only produce a column of `n/a`. The omission is reported
    /// instead, which is what turns it from invisible into measurable.
    pub fn complete_task(
        &self,
        id: &str,
        agent: &str,
        evidence: &ConformanceEvidence,
        check: &ConformanceCheck,
        learned: Option<&str>,
    ) -> Result<Completion> {
        let now = now_unix();
        let agent = self.resolve_agent(agent)?;
        let task = self
            .store
            .get_task(id)?
            .ok_or_else(|| LodestarError::NotFound(id.to_string()))?;
        self.validate_claim_evidence(&task, agent, evidence, now)?;
        let serialized = serde_json::to_string(evidence)?;
        let record = self
            .store
            .conformance_record(check.id)?
            .ok_or_else(|| LodestarError::NotFound(format!("conformance check {}", check.id)))?;
        let findings = check.findings.join("; ");
        let claim_started_at = task.claim_started_at.unwrap_or(now);
        if record.task_id.as_deref() != Some(id)
            || record.evidence_schema_version != evidence.schema_version
            || record.evidence != serialized
            || record.verdict != check.verdict
            || record.findings != findings
            || record.checked_at < claim_started_at
            || record.checked_at > now
        {
            return Err(LodestarError::Invalid(format!(
                "conformance check {} does not match the live task claim and evidence",
                check.id
            )));
        }
        let expected_token = self.conformance_token(check.id, evidence, check, Some(&task))?;
        if check.token != expected_token {
            return Err(LodestarError::Invalid(format!(
                "conformance check {} is stale; check the evidence again",
                check.id
            )));
        }
        let conformance = ConformanceResult {
            verdict: check.verdict,
            findings: check.findings.clone(),
        };
        let target_status = match conformance.verdict {
            Verdict::Aligned => TaskStatus::Done,
            Verdict::Violation => TaskStatus::Blocked,
            Verdict::Drift | Verdict::NeedsHuman => TaskStatus::InReview,
        };
        if !self.store.transition_with_checked_conformance(
            id,
            agent,
            check.id,
            conformance.verdict,
            target_status,
            now,
        )? {
            return Err(LodestarError::Invalid(format!(
                "task {id} claim changed before conformance could be recorded"
            )));
        }
        // Recorded after the transition succeeds: a lesson attached to a
        // completion that did not happen would be worse than none.
        //
        // The evidence carries the nodes this work changed, because that is the
        // only thing `apply_knowledge_advisory` matches on. Recorded as the bare
        // string `task:{id}` — which is not JSON and parses to no nodes at all —
        // every lesson an agent has ever written was stored, counted in the
        // stats, and could never reach anybody. Measured on this repository:
        // 34 of 35 active knowledge records referenced nothing.
        //
        // With the changed nodes attached, a lesson learned while changing a
        // file surfaces to the next agent who changes that file, which is both
        // the moment it is useful and the moment it was written for.
        let learned = match learned.map(str::trim).filter(|text| !text.is_empty()) {
            Some(text) => {
                let provenance = serde_json::json!({
                    "task": format!("task:{id}"),
                    "nodes": evidence.changed_node_ids,
                })
                .to_string();
                Some(self.record_knowledge(text, &provenance, None)?.id)
            }
            None => None,
        };
        Ok(Completion {
            completed: conformance.verdict == Verdict::Aligned,
            conformance,
            learned,
        })
    }

    /// Check evidence without changing task state; uses the completion evaluator.
    pub fn check_conformance(
        &self,
        evidence: &ConformanceEvidence,
        task_id: Option<&str>,
    ) -> Result<ConformanceCheck> {
        let resolved_task_id = match (task_id, evidence.task_id.as_deref()) {
            (Some(left), Some(right)) if left != right => {
                return Err(LodestarError::Invalid(
                    "evidence task_id does not match requested task".to_string(),
                ));
            }
            (Some(id), _) | (_, Some(id)) => Some(id),
            (None, None) => None,
        };
        let task = match resolved_task_id {
            Some(id) => Some(
                self.store
                    .get_task(id)?
                    .ok_or_else(|| LodestarError::NotFound(id.to_string()))?,
            ),
            None => None,
        };
        if let Some(task) = task.as_ref() {
            let agent = self.resolve_agent(&evidence.agent_id)?;
            self.validate_claim_evidence(task, agent, evidence, now_unix())?;
        } else {
            self.validate_evidence_shape(evidence)?;
        }
        let conformance = self.evaluate_conformance(evidence, task.as_ref())?;
        let serialized = serde_json::to_string(evidence)?;
        let findings = conformance.findings.join("; ");
        let id = self.store.record_conformance(
            resolved_task_id,
            ConformanceAudit {
                evidence_schema_version: evidence.schema_version,
                evidence: &serialized,
                verdict: conformance.verdict,
                findings: &findings,
            },
            now_unix(),
        )?;
        let mut checked = ConformanceCheck {
            id,
            token: String::new(),
            verdict: conformance.verdict,
            findings: conformance.findings,
        };
        checked.token = self.conformance_token(id, evidence, &checked, task.as_ref())?;
        Ok(checked)
    }

    /// The durable, append-only conformance evidence chain for a task: each
    /// record carries its stable id, the recorded evidence bundle, the verdict,
    /// findings, and when it was checked — the resolvable link proving how (and
    /// whether) the task reached completion.
    pub fn conformance_history(&self, task_id: &str) -> Result<Vec<crate::ConformanceRecord>> {
        self.store.conformance_history(task_id)
    }
}

